const _esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Başta (ya da tek başına) emoji: isteğe bağlı VS16 (FE0F) ve boşluk; en uzun eşleme önce
export const EMOJI_RE = new RegExp('^(' + Object.keys(EMOJI).sort((a, b) => b.length - a.length).map(_esc).join('|') + ')\\uFE0F?(\\s*)');
export function faIcon(name, cls = '') {
  const wrap = document.createElement('span'); wrap.innerHTML = FA[name] || FA.circle || '';
  const el = wrap.firstElementChild; if (el && cls) el.setAttribute('class', cls); return el;
}
// Metnin başındaki emojiyi FA ikonuna çevirir: [svg, kalanMetin] ya da null (eşleşme yoksa)
export function faFromText(s) {
  const m = EMOJI_RE.exec(s); if (!m) return null;
  const name = EMOJI[m[1]]; if (!FA[name]) return null;
  const rest = s.slice(m[0].length);
  return [faIcon(name, rest ? 'fa-inline' : 'fa-inline fa-solo'), rest];
}
